const errors = [];

const item = $input.first().json;

if (item.status !== "CONTACTS_FOUND") {
  errors.push("Job Status must be CONTACTS_FOUND");
}

if (!item.company_id) {
  errors.push("Missing company_id");
}

if (!item.job_id) {
  errors.push("Missing job_id");
}

if (!item.job_folder_id) {
  errors.push("Missing job_folder_id");
}

if (!item.profile_id) {
  errors.push("Missing profile_id");
}

if (errors.length > 0) {
  throw new Error(`Validation Failed: ${errors.join(" | ")}`);
}

return $input.first();

