// ---------- Input ----------
const jobId = $('Validate Inputs').first().json.job_id;
const data = $('Validate & Extract Cover Letter Info').first().json;

// ---------- Helpers ----------

function section(title) {
  return `\n${title}\n${"-".repeat(title.length)}\n`;
}

function list(arr) {
  if (!arr || !Array.isArray(arr) || arr.length === 0) return "Not available\n";
  return arr.map(item => `- ${item}`).join("\n") + "\n";
}

function value(v) {
  return v ? `${v}\n` : "Not available\n";
}

// ---------- Build Document ----------

let content =
`COVER LETTER SNAPSHOT
----------------------------------------
CANDIDATE: ${data.full_name || "Not available"}
JOB ID: ${jobId}
----------------------------------------\n`;

// Cover Letter
content += section("COVER LETTER");
content += value(data.cover_letter_text);

// Key Alignment Points
content += section("KEY ALIGNMENT POINTS");
content += list(data.key_alignment_points);

// ---------- Output ----------

return [
  {
    json: {
      job_id: jobId,
      file_type: "cover_letter",
      file_name: `Cover_Letter_Info.txt`,
      content
    }
  }
];

// ---------- Input ----------
const jobId = $('Validate Inputs').first().json.job_id;
const data = $('Validate & Extract CV Info').first().json;

// ---------- Helpers ----------

function section(title) {
  return `\n${title}\n${"-".repeat(title.length)}\n`;
}

function list(arr) {
  if (!arr || !Array.isArray(arr) || arr.length === 0) return "Not available\n";
  return arr.map(item => `- ${item}`).join("\n") + "\n";
}

function value(v) {
  return v ? `${v}\n` : "Not available\n";
}

// ---------- Build Document ----------

let content =
`CV SNAPSHOT
----------------------------------------
CANDIDATE: ${data.full_name || "Not available"}
JOB ID: ${jobId}
----------------------------------------\n`;

// Contact Info
content += section("CONTACT INFORMATION");
content += value(data.contact_information);

// Summary
content += section("PROFESSIONAL SUMMARY");
content += value(data.professional_summary);

// Education
content += section("EDUCATION");
content += list(data.education);

// Employment
content += section("EMPLOYMENT HISTORY");

if (data.employment_history && data.employment_history.length) {
  content += data.employment_history.map(job => {
    return `
${job.job_title || "Not available"}
${job.company_and_location || "Not available"}
${job.dates || "Not available"}
${list(job.responsibilities)}
`;
  }).join("\n");
} else {
  content += "Not available\n";
}

// Awards
content += section("AWARDS AND ACHIEVEMENTS");
content += list(data.awards_and_achievements);

// Skills
content += section("SKILLS");

if (data.skills && data.skills.length) {
  content += data.skills.map(skillGroup => {
    return `
${skillGroup.category || "Not available"}
${list(skillGroup.items)}
`;
  }).join("\n");
} else {
  content += "Not available\n";
}

// ---------- Output ----------

return [
  {
    json: {
      job_id: jobId,
      file_type: "cv_info",
      file_name: `CV_Info.txt`,
      content
    }
  }
];
